-import com.networknt.schema.SpecVersion;
-import com.networknt.schema.ValidationMessage;
+import com.networknt.schema.Error;
+import com.networknt.schema.Schema;
+import com.networknt.schema.SchemaRegistry;
+import com.networknt.schema.SpecificationVersion;

+/**
+ * Validates a JSON file against a JSON schema file.
+ */
 public class SchemaValidator {
+
+  /**
+   * Validates the provided JSON file against the provided JSON schema file.
+   *
+   * @param args expects two arguments: the JSON schema path and the JSON input path
+   * @throws Exception if the input cannot be read or schema validation fails
+   */
   public static void main(String[] args) throws Exception {
     if (args.length != 2) {
       throw new RuntimeException("Must provide two arguments: <json schema> <file to validate>");
@@
     JsonNode schemaNode = mapper.readTree(new File(jsonSchemaPath));
     JsonNode inputNode = mapper.readTree(new File(inputFile));

-    JsonSchemaFactory factory = JsonSchemaFactory.getInstance(SpecVersion.VersionFlag.V4);
-    JsonSchema schema = factory.getSchema(schemaNode);
+    SchemaRegistry registry = SchemaRegistry.withDefaultDialect(SpecificationVersion.DRAFT_4);
+    Schema schema = registry.getSchema(schemaNode);

-    Set<ValidationMessage> errors = schema.validate(inputNode);
+    List<Error> errors = schema.validate(inputNode);

     if (!errors.isEmpty()) {
       String messages = errors.stream()
-                              .map(ValidationMessage::getMessage)
+                              .map(Error::getMessage)
                               .collect(Collectors.joining("\n"));

       throw new RuntimeException("Schema validation errors\n" + messages);
